      // --- Tab 切换逻辑 ---
      const tabs = wrapper.querySelectorAll('.th-tab-btn');
      const contents = wrapper.querySelectorAll('.th-tab-content');
      tabs.forEach(tab => {
        tab.addEventListener('click', () => {
          tabs.forEach(t => t.classList.remove('active'));
          contents.forEach(c => c.classList.remove('active'));
          tab.classList.add('active');
          wrapper.querySelector('#' + tab.dataset.target).classList.add('active');
        });
      });

      // --- Toast 逻辑 ---
      const actionBtn = wrapper.querySelector('.js-action-btn');
      const toast = wrapper.querySelector('.js-toast');
      wrapper.querySelectorAll('.th-btn').forEach(btn => {
        btn.addEventListener('click', function() {
          const action = this.getAttribute('data-action');
          if (!action) return;
          toast.textContent = `系统指令已注入: [${action}]`;
          toast.classList.add('show');
          setTimeout(() => toast.classList.remove('show'), 2500);
        });
      });

      // --- 数据渲染核心引擎 ---
      function renderDashboard() {
        if (typeof getVariables !== 'function') return;

        // 我们利用酒馆助手的 API 取出当前楼层的 MVU JSON
        const vars = getVariables({ type: 'message' });
        const sd = vars?.stat_data || {};
        const p = sd.轮回者;
        if (!p) return;

        // 1. 顶部基础
        wrapper.querySelector('.js-name').textContent = p.姓名 || '未知轮回者';
        wrapper.querySelector('.js-role').textContent = `[${p.基本信息?.身份 || '新人'}]`;
        wrapper.querySelector('.js-pts').textContent = sd.主神货币?.奖励点 || 0;
        wrapper.querySelector('.js-xp').textContent = sd.主神货币?.经验值_XP || 0;

        const geneLv = p.生理与状态?.基因锁?.当前处于开启阶数 || 0;
        wrapper.querySelector('.js-genelock').textContent = geneLv === 0 ? '未开启' : `阶数: ${geneLv}`;
        wrapper.querySelector('.js-genelock').style.color = geneLv > 0 ? '#ef4444' : '#fff';

        // 2. 生命与意志
        const hp = p.生理与状态?.生命状态 || { 完好:5, 冲击_B:0, 严重_L:0, 恶性_A:0 };
        const maxHp = p.生理与状态?.衍生属性速查?.最大生命值 || 5;
        const hpBar = (val) => Math.min(100, (val / maxHp) * 100) + '%';
        wrapper.querySelector('.js-hp-intact').style.width = hpBar(hp.完好);
        wrapper.querySelector('.js-hp-shock').style.width = hpBar(hp.冲击_B);
        wrapper.querySelector('.js-hp-lethal').style.width = hpBar(hp.严重_L);
        wrapper.querySelector('.js-hp-aggra').style.width = hpBar(hp.恶性_A);
        wrapper.querySelector('.js-hp-val').textContent = `${hp.完好}/${maxHp}`;

        const wp = p.生理与状态?.当前意志力 || 0;
        const maxWp = p.生理与状态?.衍生属性速查?.最大意志力 || 2;
        wrapper.querySelector('.js-wp-fill').style.width = Math.min(100, (wp / maxWp) * 100) + '%';
        wrapper.querySelector('.js-wp-val').textContent = `${wp}/${maxWp}`;

        // 3. 属性九宫格
        const attrs = p.属性面板 || {};
        let attrHtml = '';
        ['力量','敏捷','耐力','智力','感知','决心','风度','操控','沉着'].forEach(k => {
          const a = attrs[k] || {当前值:1, 传奇点数:0};
          const val = a.当前值 || a.基础值 || 1;
          const leg = a.传奇点数 || 0;
          let stars = '';
          for(let i=0; i<leg; i++) stars += '<span class="th-legend-star">★</span>';
          attrHtml += `
            <div class="th-attr-card">
              <div class="th-attr-name">${k}</div>
              <div class="th-attr-val">${val}</div>
              <div style="width:30px; text-align:right;">${stars}</div>
            </div>`;
        });
        wrapper.querySelector('.js-attr-grid').innerHTML = attrHtml;

        // 4. 派生参数
        const dStats = p.生理与状态?.衍生属性速查 || {};
        const encum = p.生理与状态?.负重系统 || {当前负重_kg:0, 当前状态:'轻度'};
        const statClass = encum.当前状态 === '重度' ? '重度' : (encum.当前状态 === '压垮' ? '压垮' : '');
        wrapper.querySelector('.js-derived-grid').innerHTML = `
          <div class="th-d-stat"><span>基础防御</span> <span class="v">${dStats.基础防御 || 1}</span></div>
          <div class="th-d-stat"><span>总防御削减</span> <span class="v">${dStats.总防御 || 1}</span></div>
          <div class="th-d-stat"><span>防御附加成功</span> <span class="v" style="color:var(--accent-gold)">+${dStats.防御附加成功 || 0}</span></div>
          <div class="th-d-stat"><span>先攻</span> <span class="v">${dStats.先攻 || 2}</span></div>
          <div class="th-d-stat"><span>移动速度</span> <span class="v">${dStats.速度_米 || 10}m</span></div>
          <div class="th-d-stat"><span>当前负重</span> <span class="v ${statClass}">${encum.当前负重_kg}kg (${encum.当前状态})</span></div>
        `;

        // 5. 特质与技能
        const ttm = p.特质与模板 || {};
        const traits = Object.values(ttm.强化模板 || {}).concat(Object.values(ttm.专长列表 || {}));
        let traitHtml = traits.map(t => `
          <li class="th-trait-item">
            <div class="th-trait-header">
              <span class="th-t-name">${t.名称}</span>
              <span class="th-t-badge">${t.当前评级或层数 || (t.等级或点数+' 级') || '被动'}</span>
            </div>
            <div class="th-t-desc">${t.描述 || '无详细描述'}</div>
          </li>
        `).join('');
        wrapper.querySelector('.js-trait-list').innerHTML = traitHtml || '<span style="color:var(--text-sec);font-size:0.8rem">尚未觉醒任何特质。</span>';

        const skList = p.技能列表 || {};
        let skHtml = Object.entries(skList).map(([k, v]) => {
          if (!v || v.等级 <= 0) return '';
          return `<span class="th-skill-tag">${k} <span class="lvl">${v.等级}</span></span>`;
        }).join('');
        wrapper.querySelector('.js-skill-tags').innerHTML = skHtml || '<span style="color:var(--text-sec);font-size:0.8rem">未掌握基础技能。</span>';

        // 6. 装备与物品
        const eq = p.物品与资产 || {};
        const wLib = eq.武器库 || {};
        const aLib = eq.防具库 || {};

        // 找出已装备的物品
        const curW = Object.values(wLib).find(w => w.已装备) || { 名称: '空手', 武器伤害: '0L' };
        const curA = Object.values(aLib).find(a => a.已装备) || { 名称: '便服', 盔甲防御: '0' };

        const svgi = (path) => `<div class="th-slot-icon"><svg viewBox="0 0 24 24">${path}</svg></div>`;
        wrapper.querySelector('.js-equip-grid').innerHTML = `
          <div class="th-equip-slot">${svgi('<path d="M20.37 8.91l-8.17-8.17c-.39-.39-1.03-.39-1.42 0L2.61 8.91c-.39.39-.39 1.03 0 1.42l8.17 8.17c.39.39 1.03.39 1.42 0l8.17-8.17c.39-.38.39-1.02 0-1.42z"/>')}
            <div class="th-slot-info"><div class="th-slot-label">武器</div><div class="th-slot-name">${curW.名称}</div><div class="th-slot-sub">伤害: ${curW.武器伤害}</div></div>
          </div>
          <div class="th-equip-slot">${svgi('<path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4z"/>')}
            <div class="th-slot-info"><div class="th-slot-label">防具</div><div class="th-slot-name">${curA.名称}</div><div class="th-slot-sub">防御: ${curA.盔甲防御}</div></div>
          </div>
        `;

        const allItems = Object.values(eq.消耗品与杂物 || {});
        let invHtml = allItems.map(i => `
          <div class="th-inv-item">
            <div class="th-inv-name">${i.名称} <span style="color:var(--text-sec);font-weight:normal">x${i.数量||1}</span></div>
            <div class="th-inv-desc">${i.效果 || i.描述 || '无说明'}</div>
          </div>
        `).join('');
        wrapper.querySelector('.js-inv-list').innerHTML = invHtml || '<div style="color:var(--text-sec);font-size:0.8rem">背包空空如也。</div>';

        // 7. 主神商店
        const storeRec = sd.世界记录?.主神空间档案?.主神商店当前列表 || {};
        const storeItems = [...(storeRec.武器列表||[]), ...(storeRec.防具列表||[]), ...(storeRec.强化模板列表||[]), ...(storeRec.物品与消耗品列表||[])];
        if (storeItems.length > 0) {
          wrapper.querySelector('.js-shop-empty').style.display = 'none';
          wrapper.querySelector('.js-shop-grid').style.display = 'flex';
          wrapper.querySelector('.js-shop-grid').innerHTML = storeItems.map(i => `
            <div class="th-shop-item">
              <div class="th-shop-info">
                <div class="th-shop-name">${i.名称}</div>
                <div class="th-shop-type">${i.本质||'未知'} | ${i.分类||'强化'}</div>
              </div>
              <button class="th-btn-buy" onclick="this.closest('.th-status-wrapper').querySelector('.js-action-btn').setAttribute('data-action', '购买 ${i.名称}'); this.closest('.th-status-wrapper').querySelector('.js-action-btn').click()">
                ${i.价格 || '未知'} 兑换
              </button>
            </div>
          `).join('');
        }

        // 8. 人际网络 (NPCs)
        const npcs = sd.人物关系记录 || {};
        let npcHtml = Object.entries(npcs).map(([k, n]) => {
          const rel = n.关系记录 || {};
          const statusList = n.生理与状态?.固有状态 || [];
          const isOnline = !statusList.includes('死亡');
          return `
            <div class="th-npc-card">
              <div class="th-npc-head">
                <span class="th-npc-name">${k} <span style="font-size:10px;color:var(--text-sec);font-weight:normal">[${n.基本信息?.身份||'未知'}]</span></span>
                <span class="th-npc-relation">${rel.关系层级 || '冷淡'}</span>
              </div>
              <div class="th-npc-bar-bg"><div class="th-npc-bar-fill" style="width:${Math.min(100, Math.max(0, (rel.好感度||0)/2))}%"></div></div>
              <div class="th-npc-desc">“ ${rel.印象简评 || '...'} ”</div>
              <div style="font-size:0.7rem; color:var(--text-sec); margin-top:4px;">位置: ${n.基本信息?.所处地点||'未知'} | 状态: ${isOnline?'活跃':'离线'}</div>
            </div>
          `;
        }).join('');
        wrapper.querySelector('.js-npc-grid').innerHTML = npcHtml || '<div style="color:var(--text-sec);font-size:0.8rem">未建立任何有效的社交链路。</div>';
      }

      // 初次渲染
      renderDashboard();

      // 绑定 MVU 更新事件，实现响应式
      if (typeof eventOn === 'function' && typeof Mvu !== 'undefined') {
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, renderDashboard);
      }
    })();
  </script>
</div>
</body>
</html>
